from .money import MAX_CENTS, amount_to_cents, cents_to_decimal, format_amount


def make_invoice(amounts):
    # Copy first so the caller's input is never touched, and so any iterable
    # works with len() below.
    items = list(amounts)
    total_cents = 0
    for item in items:
        total_cents += amount_to_cents(item)
    if total_cents > MAX_CENTS:
        raise ValueError("invoice total exceeds 1000000.00")
    return {"total": format_amount(cents_to_decimal(total_cents)), "count": len(items)}

